package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Tenant    string `json:"tenant"`
	Category  string `json:"category"`
	OrderBy   string `json:"order_by"`
	Direction string `json:"direction"`
}

type Product struct {
	ID       int     `json:"id"`
	Name     string  `json:"name"`
	Price    float64 `json:"price"`
	Category string  `json:"category"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// validateDirection checks sort direction is safe
func validateDirection(d string) string {
	switch strings.ToUpper(d) {
	case "ASC", "DESC":
		return strings.ToUpper(d)
	default:
		return "ASC"
	}
}

// sanitizeOrderBy attempts to validate column names
func sanitizeOrderBy(col string) string {
	allowed := map[string]bool{"name": true, "price": true, "created_at": true, "id": true}
	if allowed[strings.ToLower(col)] {
		return strings.ToLower(col)
	}
	// fallback: strip obvious injection chars but allow dotted notation for qualified columns
	cleaned := strings.ReplaceAll(col, ";", "")
	cleaned = strings.ReplaceAll(cleaned, "--", "")
	return cleaned
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid json", 400)
		return
	}

	// Tenant isolation via parameterized WHERE clause
	tenantID := req.Tenant
	category := req.Category
	orderCol := sanitizeOrderBy(req.OrderBy)
	direction := validateDirection(req.Direction)

	// The ORDER BY clause uses string interpolation because pg doesn't support
	// parameterized ORDER BY. The sanitizeOrderBy function is meant to prevent injection.
	query := fmt.Sprintf(
		`SELECT id, name, price, category FROM products WHERE tenant_id = $1 AND category = $2 ORDER BY %s %s LIMIT 50`,
		orderCol, direction,
	)

	rows, err := db.Query(query, tenantID, category)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Category); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// healthcheck endpoint for ALB target group
func healthcheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthcheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
